import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";

import type { AstroIntegration } from "astro";

import { SECURITY_HEADERS } from "../src/shared/server/middleware/security-headers";

const HEADERS_MARKER =
  "# Generated by plugins/security-headers-file.ts from src/shared/server/middleware/security-headers.ts. Do not edit by hand.";

/** Generate Cloudflare's static `_headers` file from the shared definitions. */
export function securityHeadersFile(): AstroIntegration {
  return {
    name: "security-headers",
    hooks: {
      "astro:build:done": async ({ dir, logger }) => {
        const headersUrl = new URL("_headers", dir);
        const existing = await readFile(headersUrl, "utf8").catch(() => "");
        const block = [
          "/*",
          ...Object.entries(SECURITY_HEADERS).map(([name, value]) => `  ${name}: ${value}`),
          "",
        ].join("\n");
        const content = `${HEADERS_MARKER}\n${block}\n${existing}`;

        await writeFile(headersUrl, content);
        logger.debug(`Updated ${fileURLToPath(headersUrl)}`);
      },
    },
  };
}
